WITH base AS (SELECT * FROM transactions WHERE account_id IN (7, 11, 40) AND (account_id IN (11, 36) OR account_id IN (34, 37, 39, 40))), transactions_stats AS (SELECT account_id, is_flagged, COUNT(*) AS transaction_count, COUNT(DISTINCT amount) AS unique_accounts FROM base GROUP BY account_id, is_flagged) SELECT account_id, is_flagged, transaction_count FROM transactions_stats ORDER BY transaction_count DESC
